    # BFS/Dijkstra to find shortest path in terms of cost sum
    # state: current number n, cost: cumulative sum of values
    pq = [(0, n)]
    visited = {n: 0}

    while pq:
        curr_cost, curr_val = heapq.heappop(pq)

        if curr_val == m:
            return curr_cost

