import heapq

def minOperations(n: int, m: int) -> int:
    # Precompute primes up to 10,000 using a sieve
    limit = 10000
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, int(limit**0.5) + 1):
        if is_prime[p]:
            for i in range(p * p, limit + 1, p):
                is_prime[i] = False

    # If start or end is prime, it's impossible
    if is_prime[n] or is_prime[m]:
        return -1

    # Dijkstra's algorithm to find minimum cost path
    # Priority Queue stores (cumulative_cost, current_value)
    pq = [(n, n)]
    visited = {n: n} # Stores the minimum cumulative cost to reach a value

    while pq:
        current_cost, curr = heapq.heappop(pq)

        if curr == m:
            return current_cost

        if current_cost > visited.get(curr, float('inf')):
            continue

        # Generate neighbors by modifying digits
        s_curr = str(curr).zfill(len(str(n)))
        for i in range(len(s_curr)):
            digit = int(s_curr[i])

            # Option 1: Increase digit (if not 9)
            if digit < 9:
                next_val = int(s_curr[:i] + str(digit + 1) + s_curr[i+1:])
                if next_val <= limit and not is_prime[next_val]:
                    new_cost = current_cost + next_val
                    if new_cost < visited.get(next_val, float('inf')):
                        visited[next_val] = new_cost
                        heapq.heappush(pq, (new_cost, next_val))

            # Option 2: Decrease digit (if not 0)
            if digit > 0:
                next_val = int(s_curr[:i] + str(digit - 1) + s_curr[i+1:])
                if next_val <= limit and not is_prime[next_val]:
                    new_cost = current_cost + next_val
                    if new_cost < visited.get(next_val, float('inf')):
                        visited[next_val] = new_cost
                        heapq.heappush(pq, (new_cost, next_val))

    return -1
