import collections

def minCostGoodCaption(caption: str) -> str:
    n = len(caption)
    if n < 3:
        return ""

    INF = float('inf')
    # dp[i][c][l] where i is prefix length, c is char index (0-25), l is block length state.
    # l=0 means current character 'c' has appeared 1 time consecutively at the end of prefix i.
    # l=1 means it has appeared 2 times.
    # l=2 means it has appeared >=3 times.
    dp = [[ [INF] * 3 for _ in range(26)] for _ in range(n + 1)]

    # Base case: prefix of length 1
    for c in range(26):
        dp[1][c][0] = abs(ord(caption[0]) - ord('a') + c)

    for i in range(2, n + 1):
        # Precompute the best previous "good" state (l=2) to start a new block.
        min_vals = []
        for cp in range(26):
            v = dp[i-1][cp][2]
            if v != INF:
                min_vals.append((v, cp))
        min_vals.sort()

        for c in range(26):
            cost = abs(ord(caption[i-1]) - ord('a') + c)
            # Option 1: Start a new block of length 1 (from a previous good state with different char)
            g_val = INF
            if min_vals:
                for v, cp in min_vals:
                    if cp != c:
                        g_val = v
                        break
            if g_val != INF:
                dp[i][c][0] = g_val + cost

            # Option 2: Extend a block of length 1 to length 2
            if dp[i-1][c][0] != INF:
                dp[i][c][1] = dp[i-1][c][0] + cost

            # Option 3: Extend a block of length 2 or >=3 to length >=3
            opt_prev = min(dp[i-1][c][1], dp[i-1][c][2])
            if opt_prev != INF:
                dp[i][c][2] = opt_prev + cost

    min_total_cost = INF
    for c in range(26):
        min_total_cost = min(min_total_cost, dp[n][c][2])

    if min_total_cost == INF:
        return ""

    # can_reach[i][c][l] is True if state (i, c, l) can reach a minimum cost good caption.
    can_reach = [[ [False] * 3 for _ in range(26)] for _ in range(n + 1)]
    for c in range(26):
        if dp[n][c][2] == min_total_cost:
            can_reach[n][c][2] = True

    for i in range(n - 1, 0, -1):
        # Precompute min values for new block transitions (cp != c)
        min_bwd_vals = []
        for cp in range(26):
            if can_reach[i][cp][2]:
                min_bwd_vals.append((dp[i][cp][2], cp))
        min_bwd_vals.sort()

        for c in range(26):
            cost = abs(ord(caption[i]) - ord('a') + c) # Cost for position i+1 (index i)
            # Note: dp[i] refers to prefix length i, which used caption[i-1].
            # We are looking at transitions from state i to i+1.
            # Transition 0 -> 1:
            if dp[i][c][0] + cost == dp[i+1][c][1] and can_reach[i+1][c][1]:
                can_reach[i][c][0] = True
            # Transition 1 -> 2:
            if dp[i][c][1] + cost == dp[i+1][c][2] and can_reach[i+1][c][2]:
                can_reach[i][c][1] = True
            # Transition 2 -> 2:
            if dp[i][c][2] + cost == dp[i+1][c][2] and can_reach[i+1][c][2]:
                can_reach[i][c][2] = True
            # Transition new block (cp, 2) -> (c, 0):
            for v, cp in min_bwd_vals:
                if cp != c:
                    if dp[i][cp][2] + cost == dp[i+1][c][0] and can_reach[i+1][c][0]:
                        can_reach[i][cp][2] = True
                        break

    # Reconstruct the lexicographically smallest string.
    res = []
    curr_l = -1
    curr_c = -1

    # Find first state (1, c, 0) that is can_reach
    for c in range(26):
        if can_reach[1][c][0]:
            curr_c = c
            curr_l = 0
            break

    if curr_c == -1: return ""
    res.append(chr(ord('a') + curr_c))

    for i in range(2, n + 1):
        # We are at prefix length i-1, state (i-1, curr_c, curr_l)
        # We want to find the smallest c such that there is a transition to some l' where can_reach[i][c][l'] is true.
        found = False
        for c in range(26):
            cost = abs(ord(caption[i-1]) - ord('a') + c)
            # Check transitions from curr_l at i-1 to some l' at i
            next_l = -1
            if curr_l == 0:
                if dp[i-1][curr_c][0] + cost == dp[i][c][1]: next_l = 1
            elif curr_l == 1:
                if dp[i-1][curr_c][1] + cost == dp[i][c][2]: next_l = 2
            elif curr_l == 2:
                # Case A: Extend block of c
                if dp[i-1][curr_c][2] + cost == dp[i][c][2]: next_l = 2
                # Case B: Start new block of c (from some cp != c)
                # This is only possible if there was a good state at i-1 with char cp != c.
                # But our current logic doesn't track which cp it was, except that we know
                # dp[i][c][0] = min_{cp!=c} dp[i-1][cp][2] + cost.
                # So if dp[i][c][0] == dp[i-1][some_cp][2] + cost and can_reach[i][c][0]:
                # Actually, we just need to check if there exists ANY cp != c such that 
                # (i-1, cp, 2) was good and leads to (i, c, 0).
                # This is true if dp[i][c][0] == g_val + cost where g_val is the min of dp[i-1][cp][2] for cp != c.
                g_val = INF
                min_vals_prev = []
                for cp in range(26):
                    v = dp[i-1][cp][2]
                    if v != INF: min_vals_prev.append((v, cp))
                min_vals_prev.sort()
                for v, cp in min_vals_prev:
                    if cp != c:
                        g_val = v
                        break
                if g_val != INF and dp[i][c][0] == g_val + cost and can_reach[i][c][0]:
                    # This is a valid transition to l=0. Since we want smallest string, 
                    # we check if this c works.
                    next_l = 0

            if next_l != -1 and can_reach[i][c][next_l]:
                res.append(chr(ord('a') + c))
                curr_c = c
                curr_l = next_l
                found = True
                break
    return "".join(res)

