import heapq

def resultsArray(queries, k):
    res = []
    max_heap = []
    for x, y in queries:
        dist = abs(x) + abs(y)
        if len(max_heap) < k:
            heapq.heappush(max_heap, -dist)
        elif dist < -max_heap[0]:
            heapq.heapreplace(max_heap, -dist)

        if len(max_heap) < k:
            res.append(-1)
        else:
            res.append(-max_heap[0])
    return res
